// Enhanced Input Parser & Validator
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  let source, property_name, check_in, check_out, channelType, contactId, chatId;

  // DETERMINE SOURCE AND EXTRACT DATA
  if (data.body && data.body.property_name) {
    // Webhook input
    source = 'webhook';
    property_name = data.body.property_name;
    check_in = data.body.check_in;
    check_out = data.body.check_out;
    channelType = null;
    contactId = null;
  } 
  else {
    // Command input (Telegram or WhatsApp)
    source = 'command';

    // Extract message text
    let text = '';
    if (data.message && data.message.text) {
      // Telegram
      text = data.message.text;
      channelType = 'telegram';
      contactId = data.message.from.id ? data.message.from.id.toString() : null;
      chatId = data.message.chat.id ? data.message.chat.id.toString() : null;
    } 
    else if (data.text && data.text.body) {
      // WhatsApp
      text = data.text.body;
      channelType = 'whatsapp';
      contactId = data.from;
    }
    else if (data.Body) {
      // SMS/Twilio
      text = data.Body;
      channelType = 'sms';
      contactId = data.From;
    }

    // Parse command format: /availability PropertyName YYYY-MM-DD YYYY-MM-DD
    const parts = text.trim().split(/\s+/);

    // Check if command has correct number of parts
    if (parts.length !== 4 || !parts[0].startsWith('/availability')) {
      results.push({
        json: {
          error: true,
          error_type: 'invalid_format',
          message: '❌ *Invalid Format*\n\nCorrect usage:\n`/availability PropertyName YYYY-MM-DD YYYY-MM-DD`\n\nExample:\n`/availability Villa2024 2025-03-15 2025-03-20`',
          channel_type: channelType,
          contact_id: contactId,
          chat_id: chatId
        }
      });
      continue;
    }

    property_name = parts[1];
    check_in = parts[2];
    check_out = parts[3];
  }

  // VALIDATE DATES
  const checkInDate = new Date(check_in);
  const checkOutDate = new Date(check_out);
  const now = new Date();
  now.setHours(0, 0, 0, 0); // Reset to start of day for comparison

  // Check if dates are valid
  if (isNaN(checkInDate.getTime()) || isNaN(checkOutDate.getTime())) {
    results.push({
      json: {
        error: true,
        error_type: 'invalid_date',
        message: '❌ *Invalid Date Format*\n\nDates must be in YYYY-MM-DD format\n\nExample:\n`/availability Villa2024 2025-03-15 2025-03-20`',
        channel_type: channelType,
        contact_id: contactId,
        chat_id: chatId
      }
    });
    continue;
  }

  // Check if check-in is in the past
  if (checkInDate < now) {
    results.push({
      json: {
        error: true,
        error_type: 'past_date',
        message: '❌ *Check-in Date in Past*\n\nCheck-in date must be today or in the future\n\nPlease choose a future date.',
        channel_type: channelType,
        contact_id: contactId,
        chat_id: chatId
      }
    });
    continue;
  }

  // Check if check-out is after check-in
  if (checkOutDate <= checkInDate) {
    results.push({
      json: {
        error: true,
        error_type: 'invalid_date_range',
        message: '❌ *Invalid Date Range*\n\nCheck-out date must be after check-in date\n\nPlease correct your dates.',
        channel_type: channelType,
        contact_id: contactId,
        chat_id: chatId
      }
    });
    continue;
  }

  // Calculate nights
  const nights = Math.ceil((checkOutDate - checkInDate) / (1000 * 60 * 60 * 24));

  // Check for reasonable stay length (optional validation)
  if (nights > 365) {
    results.push({
      json: {
        error: true,
        error_type: 'stay_too_long',
        message: '❌ *Stay Too Long*\n\nMaximum stay duration is 365 nights\n\nPlease choose a shorter date range.',
        channel_type: channelType,
        contact_id: contactId,
        chat_id: chatId
      }
    });
    continue;
  }

  // Valid input - proceed to availability check
  results.push({
    json: {
      source: source,
      property_name: property_name,
      check_in: check_in,
      check_out: check_out,
      check_in_date: checkInDate.toISOString(),
      check_out_date: checkOutDate.toISOString(),
      nights: nights,
      channel_type: channelType,
      contact_id: contactId,
      chat_id: chatId,
      error: false
    }
  });
}

return results;

// Enhanced Conflict Detection with Date Overlap Logic
const requestData = $('Input Parser & Validator').first().json;
const calendarEvents = $('Query Calendar Events').all();
const deals = $('Query Active Deals').all();

const requestStart = new Date(requestData.check_in);
const requestEnd = new Date(requestData.check_out);

// Helper function to check date overlap
const hasOverlap = (start1, end1, start2, end2) => {
  // Overlap exists if: start1 < end2 AND end1 > start2
  return start1 < end2 && end1 > start2;
};

const conflicts = [];

// CHECK CALENDAR EVENTS
calendarEvents.forEach(event => {
  const e = event.json;

  // Skip if no start/end times
  if (!e.start || !e.end) return;

  // Parse event dates
  const eventStart = new Date(e.start.date || e.start.dateTime);
  const eventEnd = new Date(e.end.date || e.end.dateTime);

  // Check for overlap
  if (hasOverlap(requestStart, requestEnd, eventStart, eventEnd)) {
    conflicts.push({
      type: 'calendar',
      source: 'calendar_block',
      summary: e.summary || 'Blocked Date',
      start_date: eventStart.toISOString().split('T')[0],
      end_date: eventEnd.toISOString().split('T')[0],
      description: e.description || null
    });
  }
});

// CHECK ACTIVE DEALS
deals.forEach(deal => {
  const d = deal.json;

  // Skip if deal is for different property
  if (d.property_name !== requestData.property_name) return;

  // Skip if deal is not in active status
  const activeStatuses = ['pending', 'approved', 'negotiation'];
  if (!activeStatuses.includes(d.status)) return;

  // Parse deal dates
  const dealStart = new Date(d.check_in_date);
  const dealEnd = new Date(d.check_out_date);

  // Validate dates
  if (isNaN(dealStart.getTime()) || isNaN(dealEnd.getTime())) return;

  // Check for overlap
  if (hasOverlap(requestStart, requestEnd, dealStart, dealEnd)) {
    conflicts.push({
      type: 'deal',
      source: 'active_booking',
      client_name: d.client_name || 'Guest',
      deal_status: d.status,
      start_date: d.check_in_date,
      end_date: d.check_out_date,
      deal_id: d.deal_id
    });
  }
});

// Determine availability
const isAvailable = conflicts.length === 0;

// Calculate pricing if available (optional)
let estimatedPrice = null;
if (isAvailable && requestData.nights) {
  // This would typically come from property configuration
  // For now, using placeholder logic
  estimatedPrice = requestData.nights * 150; // $150/night placeholder
}

return [{
  json: {
    is_available: isAvailable,
    property_name: requestData.property_name,
    check_in: requestData.check_in,
    check_out: requestData.check_out,
    nights: requestData.nights,
    conflicts: conflicts,
    conflict_count: conflicts.length,
    estimated_price: estimatedPrice,
    source: requestData.source,
    channel_type: requestData.channel_type,
    contact_id: requestData.contact_id,
    chat_id: requestData.chat_id,
    checked_at: new Date().toISOString()
  }
}];

