// Format Clear Availability Response
const data = $json;

let message, keyboard;

if (data.is_available) {
  // AVAILABLE RESPONSE
  message = `✅ *AVAILABLE*\n━━━━━━━━━━━━━━━━━━━━\n\n`;
  message += `📍 Property: ${data.property_name}\n`;
  message += `📅 Check-in: ${data.check_in}\n`;
  message += `📅 Check-out: ${data.check_out}\n`;
  message += `🌙 Nights: ${data.nights}\n`;

  if (data.estimated_price) {
    message += `💰 Est. Price: $${data.estimated_price}\n`;
  }

  message += `\n🎉 *This property is available!*\n\n`;
  message += `━━━━━━━━━━━━━━━━━━━━`;

  keyboard = {
    inline_keyboard: [
      [{text: '✓ Create Booking', callback_data: `book_${data.property_name}`}],
      [{text: '🔍 Check Other Dates', callback_data: 'check_other'}],
      [{text: '🏠 View All Properties', callback_data: 'all_properties'}],
      [{text: '🏡 Dashboard', callback_data: 'dashboard'}]
    ]
  };
} else {
  // NOT AVAILABLE RESPONSE
  message = `❌ *NOT AVAILABLE*\n━━━━━━━━━━━━━━━━━━━━\n\n`;
  message += `📍 Property: ${data.property_name}\n`;
  message += `📅 Check-in: ${data.check_in}\n`;
  message += `📅 Check-out: ${data.check_out}\n`;
  message += `🌙 Nights: ${data.nights}\n\n`;
  message += `*Conflicts Found (${data.conflict_count}):*\n\n`;

  data.conflicts.forEach((c, index) => {
    message += `${index + 1}. `;

    if (c.type === 'calendar') {
      message += `📅 *${c.summary}*\n`;
      message += `   Dates: ${c.start_date} → ${c.end_date}\n`;
    } else if (c.type === 'deal') {
      message += `👤 *${c.client_name}* (${c.deal_status})\n`;
      message += `   Dates: ${c.start_date} → ${c.end_date}\n`;
    }

    message += `\n`;
  });

  message += `━━━━━━━━━━━━━━━━━━━━\n`;
  message += `💡 Try different dates or check other properties`;

  keyboard = {
    inline_keyboard: [
      [{text: '🔍 Check Other Dates', callback_data: 'check_other'}],
      [{text: '🏠 View Alternative Properties', callback_data: 'alternatives'}],
      [{text: '🏡 Dashboard', callback_data: 'dashboard'}]
    ]
  };
}

return [{
  json: {
    message: message,
    keyboard: keyboard,
    channel_type: data.channel_type,
    contact_id: data.contact_id,
    chat_id: data.chat_id
  }
}];

// Format for WhatsApp (max 3 buttons)
const data = $input.first().json;

const buttons = data.keyboard.inline_keyboard
  .slice(0, 3)
  .map(row => ({
    type: 'reply',
    reply: {
      id: row[0].callback_data,
      title: row[0].text.substring(0, 20)
    }
  }));

return [{
  json: {
    to: data.contact_id,
    body: data.message,
    buttons: buttons
  }
}];
